class Solution {
public:
    int visibleMountains(vector<vector<int>>& peaks) {
        vector<pair<int, int>> ranges;
        for (auto& p : peaks) ranges.push_back({p[0] - p[1], p[0] + p[1]});
        sort(ranges.begin(), ranges.end(), [](pair<int,int> a, pair<int,int> b) {
            return a.first != b.first ? a.first < b.first : a.second > b.second;
        });
        int answer = 0, farthest = INT_MIN;
        for (int i = 0; i < (int)ranges.size(); ++i) {
            if (ranges[i].second > farthest) {
                if (i + 1 == (int)ranges.size() || ranges[i] != ranges[i + 1]) ++answer;
                farthest = ranges[i].second;
            }
        }
        return answer;
    }
};
